my_builder = F90Builder("my_f90_builder")

pauli_table = {
    "0": {"0": ("0", 0), "x": ("x", 0), "y": ("y", 0), "z": ("z", 0)},
    "x": {"0": ("x", 0), "x": ("0", 0), "y": ("z", 1), "z": ("y", 3)},
    "y": {"0": ("y", 0), "x": ("z", 3), "y": ("0", 0), "z": ("x", 1)},
    "z": {"0": ("z", 0), "x": ("y", 1), "y": ("x", 3), "z": ("0", 0)},
}


def all_pauli_strings(string_size, prefix=""):
    """Recursively generate all pauli strings of given string_size"""
    if string_size <= 0:
        yield prefix
    else:
        yield from all_pauli_strings(string_size - 1, prefix=f"{prefix}x")
        yield from all_pauli_strings(string_size - 1, prefix=f"{prefix}y")
        yield from all_pauli_strings(string_size - 1, prefix=f"{prefix}z")


def pauli_mul(string_a, string_b, coeff_phase=0):
    """multiply two pauli strings of same length"""
    assert len(string_a) == len(string_b)
    result = ""
    for letter_a, letter_b in zip(string_a, string_b):
        letter, letter_phase = pauli_table[letter_a][letter_b]
        result += letter
        coeff_phase += letter_phase
    return result, coeff_phase & 3


def pad_pauli_string(reduced, nums, size):
    """Create a padded string from a reduced string.
    E.g. having a string xyz at spins 2,4,6 in a subspace of length 8,
    we call pad_pauli_string('xyz', (2,4,6), 8) and receive '0x0y0z00'.
    """
    padded = ["0"] * size
    for letter, num in zip(reduced, nums):
        padded[num] = letter
    return "".join(padded)


def simplify_pauli_string(padded):
    """Reduce a string, i.e. invert the padding as opposed to pad_pauli_string.
    From '0x0y0z00' we get 'xyz', (2,4,6).
    """
    nums = []
    reduced = ""
    for num, letter in enumerate(padded):
        if letter == "0":
            continue
        nums.append(num)
        reduced += letter
    return reduced, tuple(nums)


def all_spin_groups(size, num_spins, collect=[]):
    """
    Recursively generate all spin groups made from <num_spins> spins that you
    can find in a subspace of size <size>.
    """
    if size == 0:
        yield tuple(collect)
    else:
        for num in range(max(collect + [-1]) + 1, num_spins):
            yield from all_spin_groups(size - 1, num_spins, collect + [num])


def triple_pattern(string_a, string_b, string_c):
    """
    As will be shown below, the operations group into basic patterns that can be
    identified from the location of the non-identity contributions in the pauli
    strings of inputs and output. This routine provides a pattern-tuple that
    directly associates the proper suboperation to it.
    """
    pat_a = ""
    pat_b = ""
    pat_c = ""
    assert len(string_a) == len(string_b) == len(string_c)
    for let_a, let_b, let_c in zip(string_a, string_b, string_c):
        if let_a != "0" or let_b != "0" or let_c != "0":
            pat_a += "X" if let_a in "xyz" else "_"
            pat_b += "X" if let_b in "xyz" else "_"
            pat_c += "X" if let_c in "xyz" else "_"
    return (pat_a, pat_b, pat_c)


def nice_phase(integer_phase):
    """aux routine to express the complex phase in a nice way"""
    integer_phase %= 4
    if integer_phase == 0:
        return ""
    if integer_phase == 2:
        return "- "
    if integer_phase == 1:
        return "i "
    if integer_phase == 3:
        return "-i "
    raise RuntimeError("you should never see this.")


#######################################################################

# in this dictionary we remember the the individual keymaps for later
inner_keymaps_system = {}

# a parent keymap for the state of the system
system_keymap = KeyMap(name="system")
system_explore_keymap = KeyMap(name="system explore")

# the scalar contribution...
scalar_keymap = KeyMap(name="pauli_0")
# ... has only a single entry that we identify by the empty string
scalar_keymap.entry("")

# we will link the individual component keymaps for size n to all the spin groups that
# have size n. For the scalar keymap (no spins included), this is the empty tuple
system_keymap.link(tuple(), scalar_keymap)
inner_keymaps_system[0] = scalar_keymap

# we use a set of fewer spins to explore the various auxiliary routines, but we will
# apply them in large scale to the full model
system_explore_keymap.link(tuple(), scalar_keymap)


# using the aux methods from before, we can now conveniently generate the spin index
# groups of size n and the components for size n
for size in range(1, MAX_SIZE + 1):
    # we create the component keymap of size <size>. For size 2, this is xx, xy, ... zz
    keymap = KeyMap(name=f"pauli_{size}")
    for substring in all_pauli_strings(size):
        keymap.entry(substring)
    inner_keymaps_system[size] = keymap
    # now, for every spin index tuple of size <size>, we associate that component keymap
    # to it
    for number_tuple in all_spin_groups(size, NUM_SPINS):
        system_keymap.link(number_tuple, keymap)
    for number_tuple in all_spin_groups(size, NUM_SPINS_EXPLORE):
        system_explore_keymap.link(number_tuple, keymap)


#######################################################################


inner_keymaps_hamilt = {}
hamilton_keymap = KeyMap(name="hamiltonian")
hamilton_explore_keymap = KeyMap(name="hamiltonian explore")

