import numpy as np

size_ham = len(hamilton_keymap)
size_rho = len(system_keymap)
size_res = len(system_keymap)

rho_real = np.zeros(size_rho)
rho_imag = np.zeros(size_rho)
ham_real = np.zeros(size_ham)
ham_imag = np.zeros(size_ham)
res_real = np.zeros(size_res)
res_imag = np.zeros(size_res)

# let's select some specific indices
idx_rho_1x = system_keymap.key2off((1,), "x")
idx_rho_2x = system_keymap.key2off((2,), "x")
idx_rho_1y = system_keymap.key2off((1,), "y")
idx_rho_1z = system_keymap.key2off((1,), "z")

idx_rho_12yx = system_keymap.key2off((1, 2), "yx")

idx_ham_12xx = hamilton_keymap.key2off((1, 2), "xx")

rho_real[idx_rho_1z] = 1
rho_real[idx_rho_1x] = 1
ham_real[idx_ham_12xx] = 1

# x0 * xx should give 0x
# z0 * xx should give i yx

res_real, res_imag = pauli_library_eff.multiply(
    rho_real, rho_imag, ham_real, ham_imag
)

print("x @ 2:", res_real[idx_rho_2x])
print("xy @ 12:", res_imag[idx_rho_12yx])

print(
    """
As you can see, the results are consistent with what you would expect, you see 1's in the
entries that should indeed have ones.


To make the test more complete, let us have all potential combinations of 3 spins tested as
an input and compare it to the numerically exact result from matrix multiplication.
"""
)

# define the paulis to construct the matrices from the strings
paulis = {
    "0": np.eye(2).astype(np.complex128),
    "x": np.reshape([0, 1, 1, 0], (2, 2)).astype(np.complex128),
    "y": np.reshape([0, -1j, 1j, 0], (2, 2)).astype(np.complex128),
    "z": np.reshape([1, 0, 0, -1], (2, 2)).astype(np.complex128),
}

# there are not so many, so let us collect them
operators = {}

# prepare all possible operator combinations
for spin_a in ["0", "x", "y", "z"]:
    for spin_b in ["0", "x", "y", "z"]:
        for spin_c in ["0", "x", "y", "z"]:
            operators[spin_a + spin_b + spin_c] = np.kron(
                paulis[spin_a], np.kron(paulis[spin_b], paulis[spin_c])
            )

rho_real = np.zeros(len(system_keymap))
rho_imag = np.zeros(len(system_keymap))
ham_real = np.zeros(len(hamilton_keymap))
ham_imag = np.zeros(len(hamilton_keymap))

for key_left, op_left in operators.items():
    for key_right, op_right in operators.items():
        reference_result = np.dot(op_left, op_right)

        string_left, nums_left = simplify_pauli_string(key_left)
        string_right, nums_right = simplify_pauli_string(key_right)

        entry_index_left = system_keymap.key2off(nums_left, string_left)
        try:
            entry_index_right = hamilton_keymap.key2off(
                nums_right, string_right
            )

        except KeyError as exc:
            continue

        rho_real *= 0
        rho_real[entry_index_left] = 1

        ham_real *= 0
        ham_real[entry_index_right] = 1

        res_real, res_imag = pauli_library_eff.multiply(
            rho_real, rho_imag, ham_real, ham_imag
        )

        result = 0
        # for num, key in enumerate(system_keymap.keys(recursive=True)):
        #     assert system_keymap.key2off(*key.labels) == num

        targets = []

        for coeff_real, coeff_imag, key in zip(
            res_real, res_imag, system_keymap.keys(recursive=True)
        ):
            nums_target, string_target = key.labels
            target_string = pad_pauli_string(string_target, nums_target, 3)
            result += (coeff_real + 1j * coeff_imag) * operators[target_string]
            if abs(coeff_real + 1j * coeff_imag) > 1e-12:
                targets.append(
                    (complex(coeff_real + 1j * coeff_imag), target_string)
                )

        error = np.sum(np.abs(result - reference_result))
        assert error < 1e-12
        assert len(targets) == 1

        if SHOW_EXTENDED_OUTPUT:
            print(
                key_left,
                "⋅",
                key_right,
                "->",
                " ⋅ ".join(map(str, targets[0])),
                end=", ",
            )
print("\ndone.")


from timeit import timeit

op_left = np.random.random((8, 8)) + 1j * np.random.random((8, 8))
op_right = np.random.random((8, 8)) + 1j * np.random.random((8, 8))

time_ref = timeit(
    "np.dot(op_left, op_right)",
    number=100_000,
    globals=globals(),
)
time_lib = timeit(
    "pauli_library_eff.multiply(rho_real, rho_imag, ham_real, ham_imag)",
    number=100_000,
    globals=globals(),
)

print("Is what we just did faster than numpy?")
print(f"time numpy (100 000): {time_ref}")
print(f"time library (100 000): {time_lib}")
print(
    """
No it's not (at least when I have tested it). 

But why? The benefit of being explicitely sparse does not play out yet.
Lookups are quite costly and matrix-matrix-multiplication provides very simple
structures and therefore one less lookup layer. There will however be a turning
point, at least when sparsity actually plays a role. That might either be due
to suppressed correlation terms in some compression or approximation, or it
might be due to the small number of relevant hamiltonian terms compared to the 
large Hilbert space for sufficiently many spins.
"""
)
